import{_ as a,o as n,c as e,a4 as p}from"./chunks/framework.kn7HWrZO.js";const u=JSON.parse('{"title":"dsh CLI help","description":"","frontmatter":{"editSource":"docs/cli-help.md","rawMarkdownPath":"en/reference/cli-help.md"},"headers":[],"relativePath":"en/reference/cli-help.md","filePath":"en/reference/cli-help.md"}'),l={name:"en/reference/cli-help.md"};function i(t,s,o,d,c,r){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="dsh-cli-help" tabindex="-1">dsh CLI help <a class="header-anchor" href="#dsh-cli-help" aria-label="Permalink to &quot;dsh CLI help&quot;">​</a></h1><p>This reference contains complete help for the launcher, subcommands, and shipped profiles. Identical help appears once with every invocation listed. Help output retains its original language.</p><p>Run <code>pnpm run gen-cli-help</code> to regenerate; run <code>pnpm run verify-cli-help</code> to check freshness.</p><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to &quot;Contents&quot;">​</a></h2><ul><li><a href="#dsh"><code>dsh</code></a></li><li><a href="#dsh-plugin"><code>dsh plugin</code></a></li><li><a href="#dsh-acp"><code>dsh acp</code></a></li><li><a href="#dsh-headless"><code>dsh headless</code></a></li><li><a href="#dsh-sdk"><code>dsh sdk</code></a></li><li><a href="#dsh-sdk-minimal"><code>dsh sdk-minimal</code></a></li><li><a href="#dsh-web"><code>dsh web</code></a></li></ul><p><a id="dsh"></a></p><h2 id="dsh" tabindex="-1"><code>dsh</code> <a class="header-anchor" href="#dsh" aria-label="Permalink to &quot;\`dsh\`&quot;">​</a></h2><p>Invocations: <code>dsh --help</code></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: dsh [--profile] &lt;name&gt; [options] [app-args...]</span></span>
<span class="line"><span>       dsh plugin --profile &lt;name&gt; &lt;pnpm-args...&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>dsh: boot a DeepSeek Harness profile — an ordered stack of plugin-bundle patch</span></span>
<span class="line"><span>layers under your own overrides.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Arguments:</span></span>
<span class="line"><span>  args                           arguments for the booted profile&#39;s app (see:</span></span>
<span class="line"><span>                                 dsh --profile &lt;name&gt; --help)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -V, --version                  output the version number</span></span>
<span class="line"><span>  --profile &lt;name&gt;               the profile under $DSH_HOME/profiles to boot</span></span>
<span class="line"><span>  --from-default-profile &lt;name&gt;  replace a custom profile with a fresh copy of a</span></span>
<span class="line"><span>                                 shipped profile template</span></span>
<span class="line"><span>  --patch &lt;path&gt;                 extra patch-list overlay applied after the</span></span>
<span class="line"><span>                                 profile layer (repeatable)</span></span>
<span class="line"><span>  --dump-config                  print the composed profile tree and exit</span></span>
<span class="line"><span>  --dump-config-schema           print JSON Schema for profile entries and</span></span>
<span class="line"><span>                                 patches without mounting</span></span>
<span class="line"><span>  --dump-default-config          print the profile tree without its user layer</span></span>
<span class="line"><span>                                 or --patch overlays and exit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Examples:</span></span>
<span class="line"><span>  dsh web                                   boot the web profile (same as: dsh --profile web)</span></span>
<span class="line"><span>  dsh rescue --from-default-profile web</span></span>
<span class="line"><span>                                            recreate rescue from the shipped web template, then boot it</span></span>
<span class="line"><span>  dsh headless &quot;run the tests&quot;              answer one task, print the result, and exit</span></span>
<span class="line"><span>  dsh tui --patch ./extra.yml               boot a custom profile with one extra overlay</span></span>
<span class="line"><span>  dsh tui --resume &lt;session&gt;                arguments after the launcher flags reach the app</span></span>
<span class="line"><span>  dsh web --help                            the web app&#39;s own flags and help</span></span>
<span class="line"><span>  dsh plugin --profile tui add &lt;package&gt;    install a plugin into the tui profile</span></span></code></pre></div><p><a id="dsh-plugin"></a></p><h2 id="dsh-plugin" tabindex="-1"><code>dsh plugin</code> <a class="header-anchor" href="#dsh-plugin" aria-label="Permalink to &quot;\`dsh plugin\`&quot;">​</a></h2><p>Invocations: <code>dsh plugin --help</code></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: dsh plugin [options] [args...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>manage a profile&#39;s plugins by forwarding the remaining arguments to pnpm in the</span></span>
<span class="line"><span>profile directory</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Arguments:</span></span>
<span class="line"><span>  args              pnpm arguments, forwarded verbatim (add &lt;pkg&gt;, remove &lt;pkg&gt;,</span></span>
<span class="line"><span>                    why &lt;pkg&gt;, ...)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  --profile &lt;name&gt;  the profile whose plugins to manage (initialized on first</span></span>
<span class="line"><span>                    use)</span></span>
<span class="line"><span>  -h, --help        show this help</span></span></code></pre></div><p><a id="dsh-acp"></a></p><h2 id="dsh-acp" tabindex="-1"><code>dsh acp</code> <a class="header-anchor" href="#dsh-acp" aria-label="Permalink to &quot;\`dsh acp\`&quot;">​</a></h2><p>Invocations: <code>dsh acp --help</code>, <code>dsh --profile acp --help</code></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: dsh --profile acp [options]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Serve automation clients over Agent Client Protocol stdio.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -h, --help  show this help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Example:</span></span>
<span class="line"><span>  dsh --profile acp     serve ACP until the client disconnects</span></span></code></pre></div><p><a id="dsh-headless"></a></p><h2 id="dsh-headless" tabindex="-1"><code>dsh headless</code> <a class="header-anchor" href="#dsh-headless" aria-label="Permalink to &quot;\`dsh headless\`&quot;">​</a></h2><p>Invocations: <code>dsh headless --help</code>, <code>dsh --profile headless --help</code></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: dsh --profile headless [options] [task...]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Answer one task and exit; the answer goes to stdout and diagnostics to stderr.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Arguments:</span></span>
<span class="line"><span>  task                        the task text; multiple words are joined by</span></span>
<span class="line"><span>                              spaces, and \`-\` reads stdin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  --json                      write newline-delimited run events to stdout</span></span>
<span class="line"><span>                              instead of the final message</span></span>
<span class="line"><span>  --session-id &lt;id&gt;           adopt the persisted Session with this id; an</span></span>
<span class="line"><span>                              unknown id is an error</span></span>
<span class="line"><span>  --permission-mode &lt;preset&gt;  select a configured permission preset for this</span></span>
<span class="line"><span>                              task, including on resume</span></span>
<span class="line"><span>  --approval-policy &lt;policy&gt;  set approval behavior after selecting the</span></span>
<span class="line"><span>                              permission preset (choices: &quot;ask&quot;, &quot;never&quot;)</span></span>
<span class="line"><span>  --add-dir &lt;path&gt;            allow an additional physical absolute directory</span></span>
<span class="line"><span>                              under workspace-write (repeatable)</span></span>
<span class="line"><span>  -h, --help                  show this help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Examples:</span></span>
<span class="line"><span>  dsh --profile headless &quot;run the tests&quot;          answer one task and exit</span></span>
<span class="line"><span>  echo &quot;run the tests&quot; | dsh --profile headless   read the task from stdin</span></span>
<span class="line"><span>  dsh --profile headless --json &quot;run the tests&quot;   emit machine-readable run events</span></span>
<span class="line"><span>  dsh --profile headless --session-id session-… &quot;continue&quot;   resume an existing Session</span></span>
<span class="line"><span>  dsh --profile headless --permission-mode workspace-write --add-dir /repo/.git &quot;commit the fix&quot;</span></span>
<span class="line"><span>                                                        grant shared Git metadata for this task</span></span></code></pre></div><p><a id="dsh-sdk"></a></p><h2 id="dsh-sdk" tabindex="-1"><code>dsh sdk</code> <a class="header-anchor" href="#dsh-sdk" aria-label="Permalink to &quot;\`dsh sdk\`&quot;">​</a></h2><p>Invocations: <code>dsh sdk --help</code>, <code>dsh --profile sdk --help</code></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: dsh --profile sdk [options]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Serve DeepSeek Harness SDK clients over stdio JSON-RPC.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -h, --help  show this help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Example:</span></span>
<span class="line"><span>  dsh --profile sdk     serve one SDK runtime until its client disconnects</span></span></code></pre></div><p><a id="dsh-sdk-minimal"></a></p><h2 id="dsh-sdk-minimal" tabindex="-1"><code>dsh sdk-minimal</code> <a class="header-anchor" href="#dsh-sdk-minimal" aria-label="Permalink to &quot;\`dsh sdk-minimal\`&quot;">​</a></h2><p>Invocations: <code>dsh sdk-minimal --help</code>, <code>dsh --profile sdk-minimal --help</code></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: dsh --profile sdk-minimal [options]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Serve DeepSeek Harness SDK clients over stdio JSON-RPC.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -h, --help  show this help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Example:</span></span>
<span class="line"><span>  dsh --profile sdk-minimal     serve one SDK runtime until its client disconnects</span></span></code></pre></div><p><a id="dsh-web"></a></p><h2 id="dsh-web" tabindex="-1"><code>dsh web</code> <a class="header-anchor" href="#dsh-web" aria-label="Permalink to &quot;\`dsh web\`&quot;">​</a></h2><p>Invocations: <code>dsh web --help</code>, <code>dsh --profile web --help</code></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Usage: dsh --profile web [options]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Serve the DeepSeek Harness browser UI.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  --host &lt;host&gt;                  bind address: one concrete IPv4 or IPv6 literal</span></span>
<span class="line"><span>                                 of a local interface; wildcard addresses are</span></span>
<span class="line"><span>                                 rejected</span></span>
<span class="line"><span>  --no-open                      do not open the Web UI in the default browser</span></span>
<span class="line"><span>  --port &lt;port&gt;                  listen port; pass 0 to let the OS pick a free</span></span>
<span class="line"><span>                                 one</span></span>
<span class="line"><span>  --public-url &lt;url&gt;             advertise this HTTP(S) root in the printed,</span></span>
<span class="line"><span>                                 opened, runtime-context, and DSH_WEB_URL forms;</span></span>
<span class="line"><span>                                 grants no trust</span></span>
<span class="line"><span>  --trusted-host &lt;authority...&gt;  extra authority the /api browser-trust fence</span></span>
<span class="line"><span>                                 accepts (host or host:port; repeatable)</span></span>
<span class="line"><span>  --tls-cert &lt;file&gt;              PEM server certificate chain; requires</span></span>
<span class="line"><span>                                 --tls-key</span></span>
<span class="line"><span>  --tls-key &lt;file&gt;               unencrypted PEM private key; requires</span></span>
<span class="line"><span>                                 --tls-cert</span></span>
<span class="line"><span>  -h, --help                     show this help</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Examples:</span></span>
<span class="line"><span>  dsh --profile web                          serve on the composed host and port</span></span>
<span class="line"><span>  dsh --profile web --no-open                serve without opening a browser</span></span>
<span class="line"><span>  dsh --profile web --port 8080              serve on another port</span></span>
<span class="line"><span>  dsh --profile web --host 10.0.0.7          bind one local interface address</span></span>
<span class="line"><span>  dsh --profile web --public-url https://app.example/ui/ --trusted-host app.example</span></span>
<span class="line"><span>                                             advertise a prefix-stripping HTTPS proxy entry and admit its authority</span></span>
<span class="line"><span>  dsh --profile web --tls-cert ./server-chain.pem --tls-key ./server-key.pem</span></span>
<span class="line"><span>                                             serve HTTPS with an existing certificate and key</span></span></code></pre></div>`,33)])])}const m=a(l,[["render",i]]);export{u as __pageData,m as default};
